/** Generated by scaffold-crud-pages. Query hooks for Cart.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchCartList,
  fetchCartById,
  createCart,
  updateCart,
  deleteCart,
  type FetchCartListParams,
} from '~/services/httpServices/cartService';
import type { CreateCartRequest, UpdateCartRequest } from '~/types/cart';

const DOMAIN = 'cart';

export function useCartList(params?: FetchCartListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchCartList(params),
  });
}

export function useCart(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchCartById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateCart() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateCartRequest) => createCart(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateCart() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateCartRequest }) =>
      updateCart(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteCart() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteCart(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
